{"description":"Find x tick mark column positions at each panel bottom spine","cmd":"python3 - <<'EOF'
from PIL import Image
import numpy as np
im = Image.open('spectrum_overview.png').convert('RGB')
a = np.array(im).astype(int)
dark = a.sum(axis=2) < 250
def ticks(spine_row):
    # tick marks appear just below the spine (1-3 px rows) as narrow dark columns
    band = dark[spine_row+1:spine_row+3, :]
    cols=[]
    for c in range(band.shape[1]):
        if band[:,c].any():
            cols.append(c)
    # group consecutive
    groups=[]
    for c in cols:
        if groups and c==groups[-1][-1]+1:
            groups[-1].append(c)
        else:
            groups.append([c])
    return groups
for name, sr in [('p1',285),('p2',614),('p3',942)]:
    g=ticks(sr)
    print(name, 'tick groups cols:', [(g0[0],g0[-1]) for g0 in g])
EOF"}

{"description":"Get y tick mark row positions for each panel","cmd":"python3 - <<'EOF'
from PIL import Image
import numpy as np
im = Image.open('spectrum_overview.png').convert('RGB')
a = np.array(im).astype(int)
dark = a.sum(axis=2) < 460
regions={'p1':(36,285),'p2':(365,614),'p3':(693,942)}
for name,(r0,r1) in regions.items():
    sub=dark[r0:r1+1, 86:94]
    rows = np.where(sub.sum(axis=1)>2)[0] + r0
    groups=[]
    for r in rows:
        if groups and r==groups[-1][-1]+1:
            groups[-1].append(r)
        else:
            groups.append([r])
    print(name, 'y tick groups:', [(g[0],g[-1]) for g in groups])
EOF"}

{"description":"OCR each y tick label for each panel","cmd":"python3 - <<'EOF'
from PIL import Image
import pytesseract
im = Image.open('spectrum_overview.png').convert('L')
# y tick labels are left of spine col 90, roughly cols 5-80
def ocr_y(r0,r1):
    crop = im.crop((0, r0-18, 84, r1+18))
    crop = crop.resize((crop.width*7, crop.height*7), Image.LANCZOS)
    txt = pytesseract.image_to_string(crop, config='--psm 7 -c tessedit_char_whitelist=0123456789')
    return txt.strip()
print('p1 y ticks:')
for r in [46,103,160,217,274]:
    print(' row', r, '=>', repr(ocr_y(r, r)))
print('p2 y ticks:')
for r in [374,431,488,545,602]:
    print(' row', r, '=>', repr(ocr_y(r, r)))
print('p3 y ticks:')
for r in [721,756,791,827,862,897,932]:
    print(' row', r, '=>', repr(ocr_y(r, r)))
EOF"}
